// ═══ Stream.reduce — standalone terminal operation ═══
BigDecimal total = trades.stream()
    .map(Trade::getAmount)
    .reduce(BigDecimal.ZERO, BigDecimal::add);  // terminal — produces value directly

// ═══ Collectors.reducing — as downstream in groupingBy ═══
Map<String, BigDecimal> totalPerSymbol = trades.stream()
    .collect(Collectors.groupingBy(Trade::getSymbol,
        Collectors.reducing(BigDecimal.ZERO, Trade::getAmount, BigDecimal::add)));
// reducing(identity, mapper, op): maps Trade→Amount, then adds per group
// CANNOT use Stream.reduce here — groupingBy needs a Collector, not a terminal!

// Three-arg Collectors.reducing:
// reducing(identity, mapper, BinaryOperator)
// identity: BigDecimal.ZERO (starting value per group)
// mapper: Trade::getAmount (extract the value to reduce)
// BinaryOperator: BigDecimal::add (combine values)
