@Test void streamReduceVsCollectorsReducing() {
    List<Integer> nums = List.of(1, 2, 3, 4, 5);

    // Stream.reduce: standalone
    int sum1 = nums.stream().reduce(0, Integer::sum);

    // Collectors.reducing: as collector
    int sum2 = nums.stream().collect(Collectors.reducing(0, Integer::sum));

    assertThat(sum1).isEqualTo(sum2);  // same result!
}

@Test void collectorsReducingAsDownstream() {
    record Item(String cat, int value) {}
    var items = List.of(new Item("A", 10), new Item("A", 20), new Item("B", 30));

    Map<String, Integer> perCat = items.stream()
        .collect(Collectors.groupingBy(Item::cat,
            Collectors.reducing(0, Item::value, Integer::sum)));
    assertThat(perCat).containsEntry("A", 30).containsEntry("B", 30);
}
