package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.assertThat;

class ReducingTest {

    record Trade(String branch, BigDecimal amount) {}

    @Test
    void reduceTerminalVsReducingDownstream() {
        var trades = List.of(
            new Trade("MUM", new BigDecimal("50000")),
            new Trade("MUM", new BigDecimal("30000")),
            new Trade("DEL", new BigDecimal("20000")));

        BigDecimal bankWide = trades.stream()
            .map(Trade::amount).reduce(BigDecimal.ZERO, BigDecimal::add); // terminal
        Map<String, BigDecimal> perBranch = trades.stream()
            .collect(Collectors.groupingBy(Trade::branch,
                     Collectors.reducing(BigDecimal.ZERO, Trade::amount, BigDecimal::add)));

        assertThat(bankWide).isEqualByComparingTo("100000");
        assertThat(perBranch.get("MUM")).isEqualByComparingTo("80000");
        assertThat(perBranch.get("DEL")).isEqualByComparingTo("20000");
    }
}
